package io.knowledgebrain.brainquery;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.assertj.core.api.Assertions.*;
class PublicStorageIntegrationTest {
 static UUID id(){return BrainProjectionIntegrationTest.id();}
 PublicProjection.Document doc(UUID id,UUID space,String kind,long sequence,boolean active,List<PublicProjection.Ref> refs){return new PublicProjection.Document(id,space,kind,1,sequence,active,"Public storage fixture","Public projection searchable needle",refs,"h"+sequence);}
 @Test @EnabledIfEnvironmentVariable(named="BRAIN_TEST_GRAPH_HOST",matches=".+") void graphPersistsTypedEdgesAcrossRestartBoundsTraversalAndIsolatesSpace()throws Exception{String host=System.getenv("BRAIN_TEST_GRAPH_HOST"),trust="/graph-trust/truststore.p12",password=Files.readString(Path.of("/graph-projector/password")).strip();try(var admin=NoteGraphStore.open(host,Files.readString(Path.of("/graph-admin/username")).strip(),Files.readString(Path.of("/graph-admin/password")).strip(),trust,password)){PublicGraphStore.initialize(admin);}var space=id();var concept=id();var claim=id();var qualifier=id();try(var graph=PublicDiscoveryConfiguration.graph(host,"/graph-projector",trust)){var c=doc(concept,space,"CONCEPT",1,true,List.of());graph.apply(c);graph.apply(c);graph.apply(doc(claim,space,"CLAIM",2,true,List.of(new PublicProjection.Ref("SUBJECT",concept))));graph.apply(doc(qualifier,space,"QUALIFIER",3,true,List.of(new PublicProjection.Ref("QUALIFIES",claim),new PublicProjection.Ref("QUALIFIER_PREDICATE",concept))));assertThat(graph.read(space,concept,1,10).nodes()).hasSize(3);assertThat(graph.read(space,concept,3,2).truncated()).isTrue();assertThat(graph.read(id(),concept,2,10).nodes()).isEmpty();assertThatThrownBy(()->graph.apply(doc(concept,id(),"CONCEPT",9,true,List.of()))).isInstanceOf(PublicProjectionStore.Conflict.class);graph.apply(doc(qualifier,space,"QUALIFIER",4,false,List.of()));assertThat(graph.read(space,null,2,10).nodes()).hasSize(2);assertThat(graph.read(space,null,2,10).edges()).hasSize(1);}try(var reopened=PublicDiscoveryConfiguration.graph(host,"/graph-projector",trust)){assertThat(reopened.read(space,concept,2,10).nodes()).hasSize(2);}}
 @Test @EnabledIfEnvironmentVariable(named="BRAIN_TEST_SEARCH_ORIGIN",matches=".+") void searchExternalSequenceRetryAndKindSpaceRetirementFilters()throws Exception{var writer=new NoteSearchClient(System.getenv("BRAIN_TEST_SEARCH_ORIGIN"),Path.of("/search-projector"));var reader=new NoteSearchClient(System.getenv("BRAIN_TEST_SEARCH_ORIGIN"),Path.of("/search-reader"));var space=id();var entity=id();var d=doc(entity,space,"QUALIFIER",1,true,List.of());writer.applyPublic(d);writer.applyPublic(d);assertThatThrownBy(()->writer.applyPublic(new PublicProjection.Document(entity,space,"QUALIFIER",1,1,true,"Conflict","Other",List.of(),"conflict"))).isInstanceOf(NoteSearchClient.Conflict.class);for(int i=0;i<40&&reader.searchPublic(space,"searchable needle",0,20,"QUALIFIER").path("total").path("value").asLong()!=1;i++)Thread.sleep(200);assertThat(reader.searchPublic(space,"searchable needle",0,20,"QUALIFIER").path("total").path("value").asLong()).isEqualTo(1);assertThat(reader.searchPublic(id(),"searchable needle",0,20,null).path("total").path("value").asLong()).isZero();writer.applyPublic(doc(entity,space,"QUALIFIER",2,false,List.of()));writer.applyPublic(d);for(int i=0;i<40&&reader.searchPublic(space,"searchable needle",0,20,null).path("total").path("value").asLong()!=0;i++)Thread.sleep(200);assertThat(reader.searchPublic(space,"searchable needle",0,20,null).path("total").path("value").asLong()).isZero();}
}
